<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Authorship\AuthorshipResidentSeatBindingService; use Symfony\Component\Console\Attribute\AsCommand; use Symfony\Component\Console\Command\Command; use Symfony\Component\Console\Input\InputArgument; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:mastermason:bind-chancellor',description:'Atomically bind the exact qualified Chancellor to Studium')]
final class MasterMasonBindChancellorCommand extends Command { public function __construct(private readonly AuthorshipResidentSeatBindingService $service){parent::__construct();} protected function configure():void{$this->addArgument('delivery-id',InputArgument::REQUIRED);} protected function execute(InputInterface $input,OutputInterface $output):int{try{$o=$this->service->bind('studium',(string)$input->getArgument('delivery-id'));}catch(\Throwable $e){$output->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$output->writeln('<info>CHANCELLOR_SEAT_BOUND</info> '.$o['binding_id']);$output->writeln('Seat: '.$o['seat']);$output->writeln('Manifestation: '.$o['manifestation_id']);$output->writeln('Status: '.$o['status']);$output->writeln('Binding atomic: YES');$output->writeln('Authorship authority: GRANTED FOR EXACT ACCEPTED COMMISSIONS');$output->writeln('Subordinate Notary resolution: PRESENT; NOT EXERCISED');$output->writeln('Recipient acceptance: NOT RECORDED');$output->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;} }
